def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl.gsl_integration_cquad.restype = ctypes.c_int

    def c_func(x):
        return func(x)

    gsl_func = GSLFunction(ctypes.CFUNCTYPE(ctypes.c_double)(c_func))
    workspace = CQuadWorkspace()

    integral = ctypes.c_double()
    n = ctypes.c_size_t()

    status = gsl.gsl_integration_cquad(
        &gsl_func, a, b, epsabs, epsrel, workspace_size, &workspace, &integral, &n
    )

    if status != 0:
        raise RuntimeError("Error during integration.")

    return {
        "Candidate_solution": f"Integral: {integral.value}, Error: {epsabs.value}, Function Evaluations: {n.value}"
    }

