    // Initialize interpolation
    gsl_interp_init(interp, x, y, 3)

    // Compute interpolated value, derivative, and integral
    double y_val, dy_val, integ_val
    gsl_interp_eval(interp, x_val, &y_val, &dy_val, &integ_val)

    // Check for errors
