def numpy_to_gsl_matrix(A):
    return gsl.gsl_matrix_alloc(A.shape[0], A.shape[1])

# Convert NumPy array to GSL vector
def numpy_to_gsl_vector(v):
    return gsl.gsl_vector_alloc(v.size)

# Compute eigenvalues of a generalized symmetric matrix
def compute_gensymm_eigenvalues(A, B):
    # Check matrix dimensions
    if A.shape != B.shape:
        raise ValueError("Matrices A and B must have the same dimensions.")

    # Convert matrices to GSL format
    A_gsl = numpy_to_gsl_matrix(A)
    B_gsl = numpy_to_gsl_matrix(B)

    # Allocate eigenvalue workspace
    ws = gsl_eigen_gensymm_workspace()
    gsl.gsl_eigen_gensymm_workspace_alloc(ws, A.shape[0])

    # Compute eigenvalues
    eigenvalues = gsl.gsl_eigen_gensymm(A_gsl, B_gsl, ws)

    # Convert eigenvalues to NumPy array
    return np.array([eigenvalues.data[i] for i in range(eigenvalues.size)])

