        median = gsl.gsl_accum_medians_get(self.accumulator)
        return median

# Function to compute the median of a moving window
def moving_median(data, window_size):
    medians = []
    accumulator = MedianAccumulator()

    for i in range(len(data)):
        accumulator.insert(data[i])

        if i >= window_size - 1:
            medians.append(accumulator.get_median())

    return medians

