        numpy_matrix = np.zeros((self.rows, self.cols), dtype=np.float64)
        for i in range(self.rows):
            for j in range(self.cols):
                numpy_matrix[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
