class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.gsl_matrix = gsl.create_gsl_matrix(len(data), len(data[0]))

    def set_elements(self):
        for i in range(len(self.data)):
            for j in range(len(self.data[0])):
                gsl.gsl_matrix_set(self.gsl_matrix, i, j, self.data[i][j])

    def get_elements(self):
        result = []
        for i in range(len(self.data)):
            row = []
            for j in range(len(self.data[0])):
                row.append(gsl.gsl_matrix_get(self.gsl_matrix, i, j))
            result.append(row)
        return result

    def free_gsl_matrix(self):
        gsl.free_gsl_matrix(self.gsl_matrix)

