def is_positive_definite(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size, (ct.c_double * size * size)())
    for i in range(size):
        for j in range(size):
            gsl_matrix.data[i * size + j] = matrix[i][j]
    gsl.gsl_matrix_set(gsl_matrix)
    return gsl.gsl_linalg_cholesky_is_pd(gsl_matrix) == 1

def cholesky_decomp(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size, (ct.c_double * size * size)())
    for i in range(size):
        for j in range(size):
            gsl_matrix.data[i * size + j] = matrix[i][j]
    gsl.gsl_matrix_set(gsl_matrix)
    gsl.gsl_linalg_cholesky_decomp(gsl_matrix)
    result = [[matrix[i][j] for j in range(i + 1)] for i in range(size)]
    return result

